// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBefore = c.getBalance(actor);
        require(balanceBefore == depositAmount, "setup failed");

        vm.prank(actor);
        c.withdrawBalance();

        uint256 balanceAfter = c.getBalance(actor);
        assertTrue(balanceAfter == 0);
    }
}
